package projection
import ("errors"; "net/http"; "testing"; "github.com/sunholo-data/ailang-world/host/broker")
func TestMission217AbsentPrecheckGenuineError(t *testing.T) {
 st:=openStore(t)
 tok:=mintToken(t,st,"ep-a",[]broker.Capability{liveGrant("alpha")})
 cfg:=testConfig(st); cfg.Heads=fixedHeads{ok:false}; cfg.Reader=errReader{err:errors.New("genuine snapshot failure")}
 rec:=getCard(t,mustHandler(t,cfg),"Bearer "+tok)
 if rec.Code != http.StatusServiceUnavailable {t.Fatalf("masked genuine failure: got status=%d body=%s; want503",rec.Code,rec.Body)}
}
